typedef unsigned int uint32_t;
typedef unsigned long size_t;

typedef struct { int cs_pin; int bus; } spi_dev_t;

void spi_acquire_bus(spi_dev_t* dev) { (void)dev; }
void spi_release_bus(spi_dev_t* dev) { (void)dev; }
void spi_flash_cmd_erase(spi_dev_t* dev, uint32_t addr) { (void)dev; (void)addr; }
void spi_flash_cmd_write(spi_dev_t* dev, uint32_t addr, const void* data, size_t len) { (void)dev; (void)addr; (void)data; (void)len; }
void spi_flash_cmd_read(spi_dev_t* dev, uint32_t addr, void* data, size_t len) { (void)dev; (void)addr; (void)data; (void)len; }
void spi_flash_wait_ready(spi_dev_t* dev) { (void)dev; }

void spi_flash_erase_write(spi_dev_t* dev, uint32_t addr, const void* data, size_t len)
{
  spi_acquire_bus(dev);
  spi_flash_cmd_erase(dev, addr);
  spi_flash_wait_ready(dev);
  spi_flash_cmd_write(dev, addr, data, len);
  spi_release_bus(dev);
}

void spi_flash_erase_write_variant(spi_dev_t* dev, uint32_t addr, const void* data, size_t len)
{
  spi_acquire_bus(dev);
  spi_flash_cmd_erase(dev, addr);
  spi_flash_wait_ready(dev);
  spi_flash_cmd_write(dev, addr, data, len);
  spi_release_bus(dev);
}

void spi_flash_read_modify_write(spi_dev_t* dev, uint32_t addr, const void* data, size_t len)
{
  char buf[256];
  spi_acquire_bus(dev);
  spi_flash_cmd_read(dev, addr, buf, len);
  spi_flash_cmd_erase(dev, addr);
  spi_flash_cmd_write(dev, addr, data, len);
  spi_release_bus(dev);
}
